INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT146-S3-Q5$batch02$, 146, 3, 5, $batch02$Flaw$batch02$, $batch02$Resident: Data indicates that 30 percent of the houses in our town have inadequate site drainage and 30 percent have structural defects that could make them unsafe. Hence, at least 60 percent of our town’s houses have some kind of problem that threatens their integrity.$batch02$, $batch02$The reasoning in the resident’s argument is flawed in that the argument overlooks the possibility that$batch02$, $batch02$E$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=146 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$the town has a relatively small number of houses$batch02$, $batch02$No Impact$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$inadequate site drainage can make a house unsafe$batch02$, $batch02$No Impact$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$structural defects are often easier to fix than inadequate site drainage$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$many houses in the town have neither inadequate site drainage nor structural defects that could make them unsafe$batch02$, $batch02$Compatible$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$some of the houses that have structural defects that could make them unsafe also have inadequate site drainage$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$At least 60 percent of houses have a problem.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$30 percent have poor drainage; 30 percent have structural defects.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Use 100 houses. Thirty have drainage problems and thirty have structural defects. If they are different houses, 60 have a problem. But what if they are the same 30 houses? Then only 30 have a problem. Adding the percentages works only if no house is on both lists. "At least 60" is really "somewhere between 30 and 60."$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for overlap between the two groups.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Percentages work the same whether the town has 100 houses or 100,000. Size does not create or remove overlap.$batch02$), ($batch02$B$batch02$, $batch02$A drainage problem already counts as a problem in the resident's math. Whether it also makes a house unsafe does not change how many houses have a problem.$batch02$), ($batch02$C$batch02$, $batch02$Ease of repair has nothing to do with how many houses have problems now.$batch02$), ($batch02$D$batch02$, $batch02$The resident's own claim leaves up to 40 percent with neither problem. "Many houses have neither" fits the argument and does not touch the addition error.$batch02$), ($batch02$E$batch02$, $batch02$If some houses have both problems, they get counted twice. With overlap, fewer than 60 percent of houses have a problem, so "at least 60 percent" fails.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT146-S3-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
